<?php
function tempNormaliseText(string $text):string{return trim(preg_replace('/[ \t]+/u',' ',preg_replace('/\R{3,}/u',"\n\n",str_replace(["\xC2\xA0","\r"],[' ',"\n"],$text))));}
function tempDetectSections(string $text):array{$aliases=['summary'=>['professional summary','summary','objective','profile'],'experience'=>['work experience','professional experience','employment','career history','experience'],'education'=>['education','academic background','qualification'],'skills'=>['technical skills','core skills','skills','technologies'],'projects'=>['projects','key projects'],'certifications'=>['certifications','certificates'],'languages'=>['languages']];$lines=preg_split('/\R/',$text);$sections=[];$current='header';foreach($lines as $line){$clean=mb_strtolower(trim(preg_replace('/[^\pL\pN +&#\/.-]/u','',$line)));$found=null;foreach($aliases as $key=>$names)if(in_array($clean,$names,true)){$found=$key;break;}if($found){$current=$found;$sections[$current]=[];continue;}if(trim($line)!=='')$sections[$current][]=trim($line);}return array_map(fn($lines)=>trim(implode("\n",$lines)),$sections);}
function tempContactData(string $text):array{preg_match('/https?:\/\/(?:www\.)?linkedin\.com\/[^\s)>]+/i',$text,$li);preg_match('/https?:\/\/(?:www\.)?github\.com\/[^\s)>]+/i',$text,$gh);preg_match_all('/https?:\/\/[^\s)>]+/i',$text,$urls);$portfolio=null;foreach($urls[0]??[] as $url)if(!str_contains(strtolower($url),'linkedin.com')&&!str_contains(strtolower($url),'github.com')){$portfolio=$url;break;}return ['email'=>extractEmail($text),'phone'=>extractPhone($text),'linkedin'=>$li[0]??null,'github'=>$gh[0]??null,'portfolio'=>$portfolio];}
function tempSkillRelations():array{return ['PHP'=>['Laravel'=>.6,'Symfony'=>.6,'CodeIgniter'=>.6],'JavaScript'=>['React'=>.6,'Angular'=>.6,'Vue.js'=>.6,'Node.js'=>.55],'Python'=>['Django'=>.6,'Flask'=>.6],'Blockchain'=>['Web3'=>.65,'Ethereum'=>.7,'Solidity'=>.65,'Smart Contracts'=>.65],'REST API'=>['Postman'=>.55]];}
function tempRoleSimilarity(string $job,string $role):int{$tokens=fn($v)=>array_values(array_unique(array_filter(preg_split('/\W+/u',mb_strtolower($v)),fn($x)=>mb_strlen($x)>2&&!in_array($x,['senior','junior','lead']))));$a=$tokens($job);$b=$tokens($role);return $a?(int)round(count(array_intersect($a,$b))/count($a)*100):0;}
function tempOverlaps(array $jobs):array{$overlaps=[];for($i=0;$i<count($jobs);$i++)for($j=$i+1;$j<count($jobs);$j++){if(($jobs[$i]['start_ts']??0)<=($jobs[$j]['end_ts']??0)&&($jobs[$j]['start_ts']??0)<=($jobs[$i]['end_ts']??0))$overlaps[]=['period'=>max($jobs[$i]['start']??'',$jobs[$j]['start']??'').' to '.min($jobs[$i]['end']??'',$jobs[$j]['end']??''),'jobs'=>[$jobs[$i]['label']??'Role', $jobs[$j]['label']??'Role']];}return $overlaps;}
function tempEvidenceAnalysis(array $candidate,array $job,string $text,array $extraction):array{$normal=tempNormaliseText($text);$sections=tempDetectSections($normal);$skills=extractDetectedSkills($normal);$timeline=analyzeExperienceTimeline($normal,$skills);$required=json_decode($job['required_skills_json']??'[]',true)?:[];$preferred=json_decode($job['preferred_skills_json']??'[]',true)?:[];$skillsSection=extractDetectedSkills($sections['skills']??'');$experienceSection=extractDetectedSkills($sections['experience']??'');$relations=tempSkillRelations();$matches=[];$mandatoryPoints=0;$evidencePoints=0;foreach($required as $req){$exact=in_array($req,$skills,true);$inExperience=in_array($req,$experienceSection,true)||isset($timeline['skill_months'][$req]);$inSkills=in_array($req,$skillsSection,true);$related=[];if(!$exact)foreach($relations[$req]??[] as $source=>$weight)if(in_array($source,$skills,true))$related[$source]=$weight;$status='missing';$confidence=0;$factor=0;if($exact&&$inExperience){$status='strong_evidence';$confidence=.95;$factor=1;}elseif($exact&&$inSkills){$status='skills_only';$confidence=.72;$factor=.75;}elseif($exact){$status='resume_evidence';$confidence=.82;$factor=.85;}elseif($related){$status='related_inferred';$confidence=max($related);$factor=max($related);}$mandatoryPoints+=$factor;$evidencePoints+=$inExperience?1:($inSkills?.55:($related?.4:0));$matches[]=['requirement'=>$req,'status'=>$status,'evidence'=>$exact?[$req]:array_keys($related),'experience_evidence'=>$inExperience,'confidence'=>$confidence,'months'=>(int)($timeline['skill_months'][$req]??0)];}$preferredMatched=array_values(array_intersect($preferred,$skills));$mandatory=count($required)?$mandatoryPoints/count($required)*40:0;$evidence=count($required)?$evidencePoints/count($required)*15:0;$relevantMonths=0;foreach($required as $req)$relevantMonths=max($relevantMonths,(int)($timeline['skill_months'][$req]??0));$minimum=(float)($job['min_experience']??0)*12;$experienceScore=$minimum>0?min(25,$relevantMonths/$minimum*25):($timeline['total_months']?25:0);$preferredScore=count($preferred)?count($preferredMatched)/count($preferred)*10:0;$roleScore=tempRoleSimilarity($job['title'],$candidate['role']??'')/100*10;$total=(int)round($mandatory+$experienceScore+$preferredScore+$roleScore+$evidence);$overlaps=tempOverlaps($timeline['jobs']);$flags=[];$contact=tempContactData($normal);if(!$contact['email'])$flags[]='Missing email';if(!$contact['phone'])$flags[]='Missing phone';if(empty($timeline['jobs']))$flags[]='No reliable employment dates';if($overlaps)$flags[]='Overlapping employment dates require review';if(!empty($timeline['gaps']))$flags[]='Employment gap above threshold';if(!isset($sections['education']))$flags[]='Education section not detected';foreach($matches as $m)if($m['status']==='skills_only')$flags[]=$m['requirement'].' listed without experience evidence';return ['candidate'=>$candidate,'contact'=>$contact,'sections'=>$sections,'skills'=>$skills,'timeline'=>$timeline,'overlaps'=>$overlaps,'requirements'=>['required'=>$required,'preferred'=>$preferred],'matches'=>$matches,'score'=>['total'=>min(100,$total),'breakdown'=>['mandatory_skills'=>round($mandatory,1),'relevant_experience'=>round($experienceScore,1),'preferred_skills'=>round($preferredScore,1),'role_similarity'=>round($roleScore,1),'evidence_strength'=>round($evidence,1)],'maximum'=>['mandatory_skills'=>40,'relevant_experience'=>25,'preferred_skills'=>10,'role_similarity'=>10,'evidence_strength'=>15]],'flags'=>array_values(array_unique($flags)),'parser'=>['file_type'=>strtoupper(pathinfo($candidate['file']??'',PATHINFO_EXTENSION)),'parser_status'=>empty($extraction['error'])?'processed':'warning','requires_ocr'=>$extraction['requires_ocr']??false,'warning'=>$extraction['error']??null,'raw_text'=>$text,'normalized_text'=>$normal],'ai_status'=>'disabled'];}
